css:
.launchpadsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2a26;
    background: linear-gradient(180deg, #f7f2e7 0%, #efe6d3 100%);
    border-radius: 18px;
}

.launchpadsim-container * {
    box-sizing: border-box;
}

.launchpadsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0c5b4e 0%, #11796a 55%, #1c8f6d 100%);
    color: #fbf7ec;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0a4a40;
    box-shadow: 0 12px 30px rgba(12, 91, 78, 0.30);
}

.launchpadsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fff8e8;
}

.launchpadsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f5d77e;
    background: rgba(245, 215, 126, 0.14);
    border: 1px solid rgba(245, 215, 126, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.launchpadsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7f1ec;
}

.launchpadsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5b5a52;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.launchpadsim-period-counter #currentDay,
.launchpadsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0c5b4e;
}

.launchpadsim-round-name {
    background: rgba(12, 91, 78, 0.12);
    color: #0c5b4e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.launchpadsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b14;
    background: rgba(214, 145, 38, 0.16);
    border: 1px solid rgba(214, 145, 38, 0.40);
    padding: 4px 12px;
    border-radius: 999px;
}

.launchpadsim-status-cards {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-bottom: 16px;
}

.launchpadsim-status-card {
    background: #fffdf6;
    border-radius: 14px;
    padding: 16px 14px 14px;
    border: 1px solid #e3d9c2;
    box-shadow: 0 6px 14px rgba(120, 100, 60, 0.12);
    border-top: 4px solid #11796a;
}

.launchpadsim-card-formation { border-top-color: #1c8f6d; }
.launchpadsim-card-highgrowth { border-top-color: #2b6fb0; }
.launchpadsim-card-survival { border-top-color: #8a5fc0; }
.launchpadsim-card-efficiency { border-top-color: #d69126; }
.launchpadsim-card-viability { border-top-color: #c0552b; }

.launchpadsim-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #7c7460;
}

.launchpadsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1c2b27;
    font-variant-numeric: tabular-nums;
}

.launchpadsim-card-formation .launchpadsim-value { color: #157a5b; }
.launchpadsim-card-highgrowth .launchpadsim-value { color: #2b6fb0; }
.launchpadsim-card-survival .launchpadsim-value { color: #7a52ad; }
.launchpadsim-card-efficiency .launchpadsim-value { color: #b87a17; }
.launchpadsim-card-viability .launchpadsim-value { color: #b34a24; }

.launchpadsim-sublabel {
    font-size: 0.72rem;
    color: #8b8369;
    line-height: 1.35;
}

.launchpadsim-viability-high { border-top-color: #1c8f6d; }
.launchpadsim-viability-high .launchpadsim-value { color: #157a5b; }
.launchpadsim-viability-low { border-top-color: #c0392b; }
.launchpadsim-viability-low .launchpadsim-value { color: #c0392b; }

.launchpadsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0c5b4e;
    border: 1px solid #0a4a40;
    color: #eaf6f1;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.launchpadsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f5d77e;
}

.launchpadsim-budget-over #budgetDisplay {
    color: #ffb4a2;
}

.launchpadsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf6;
    border-left: 5px solid #d69126;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 14px rgba(120, 100, 60, 0.10);
}

.launchpadsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.launchpadsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0c5b4e;
    margin-bottom: 6px;
}

.launchpadsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #44423a;
}

.launchpadsim-briefing-text strong { color: #11796a; }
.launchpadsim-briefing-text em { color: #b87a17; font-style: italic; }

.launchpadsim-controls {
    background: #fffdf6;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3d9c2;
    box-shadow: 0 6px 14px rgba(120, 100, 60, 0.10);
}

.launchpadsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0c5b4e;
    border-bottom: 2px solid #ece2cd;
    padding-bottom: 8px;
}

.launchpadsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3c3a32;
    margin: 14px 0 6px;
}

.launchpadsim-container select,
.launchpadsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d7cbb0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffefb;
    color: #2b2a26;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.launchpadsim-container select:focus,
.launchpadsim-container input[type="number"]:focus {
    outline: none;
    border-color: #11796a;
    box-shadow: 0 0 0 3px rgba(17, 121, 106, 0.16);
}

.launchpadsim-container select option {
    background-color: #fffefb;
    color: #2b2a26;
}

.launchpadsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #11796a;
}

.launchpadsim-range-readout,
.launchpadsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6e664f;
    margin-top: 4px;
}

.launchpadsim-range-readout span:not(:first-child),
.launchpadsim-alloc-readout span:nth-child(2) {
    color: #11796a;
    font-weight: 800;
}

.launchpadsim-hint {
    font-size: 0.8rem;
    color: #8b8369;
    margin-top: 6px;
    line-height: 1.45;
}

.launchpadsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.launchpadsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6efdf;
    border: 1px solid #e3d9c2;
    border-radius: 9px;
    padding: 8px 12px;
}

.launchpadsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3c3a32;
}

.launchpadsim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.launchpadsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.launchpadsim-container .btn-primary {
    background: linear-gradient(135deg, #0c5b4e 0%, #1c8f6d 100%);
    border: none;
    color: #fff8e8;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(12, 91, 78, 0.30);
}

.launchpadsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.launchpadsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d7cbb0;
    color: #6e664f;
    background: transparent;
}

.launchpadsim-coach {
    background: linear-gradient(160deg, #133a33 0%, #0c5b4e 100%);
    color: #eaf6f1;
    border: 1px solid #0a4a40;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(12, 91, 78, 0.22);
}

.launchpadsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f5d77e;
    margin-bottom: 8px;
}

.launchpadsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.launchpadsim-coach-body strong { color: #f5d77e; }
.launchpadsim-coach-body em { color: #ffd9a0; font-style: italic; }

.launchpadsim-history,
.launchpadsim-chart {
    background: #fffdf6;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3d9c2;
    box-shadow: 0 6px 14px rgba(120, 100, 60, 0.10);
}

.launchpadsim-history h3,
.launchpadsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0c5b4e;
}

.launchpadsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #44423a;
}

.launchpadsim-container table#usfHistoryTable th {
    background: #0c5b4e;
    color: #f5d77e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #0a4a40;
}

.launchpadsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece2cd;
    color: #44423a;
}

.launchpadsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f9f3e6;
}

.launchpadsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .launchpadsim-container {
        padding: 14px;
    }
    .launchpadsim-header h1 {
        font-size: 1.7rem;
    }
    .launchpadsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .launchpadsim-value {
        font-size: 2rem;
    }
    .launchpadsim-clock {
        margin-left: 0;
    }
    .launchpadsim-period-counter {
        font-size: 0.88rem;
    }
    .launchpadsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .launchpadsim-alloc-row {
        flex-wrap: wrap;
    }
    .launchpadsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .launchpadsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .lpd-cm-*) */
.lpd-cm { margin-top: 8px; }
.lpd-cm-incomplete { text-align: center; color: #44423a; font-size: 1rem; padding: 18px; }
.lpd-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.lpd-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0a4a40 0%, #11796a 55%, #f5d77e 150%); color: #fffdf6; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(10,74,64,0.28); }
.lpd-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.lpd-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.lpd-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f5d77e; }
.lpd-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fffdf6; border: 1px solid #e3d9c2; border-radius: 14px; padding: 14px 20px; }
.lpd-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #8a7f66; }
.lpd-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #0a4a40; margin-top: 4px; line-height: 1.15; }
.lpd-cm-section { margin-bottom: 16px; }
.lpd-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #11796a; margin-bottom: 8px; border-bottom: 1px solid #e3d9c2; padding-bottom: 4px; }
.lpd-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.lpd-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.lpd-cm-ok { background: #e2f1ea; color: #0a4a40; border-color: #bfe0d1; }
.lpd-cm-no { background: #f7e9e4; color: #9a5b1f; border-color: #ecc9b6; }
.lpd-cm-ico { font-weight: 800; }
.lpd-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.lpd-cm-kpi { background: #fffefb; border: 1px solid #e3d9c2; border-radius: 12px; padding: 12px 10px; text-align: center; }
.lpd-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #11796a; line-height: 1; }
.lpd-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #44423a; margin-top: 6px; }
.lpd-cm-kpi-sub { font-size: 0.68rem; color: #8a7f66; margin-top: 2px; }
.lpd-cm-insights { margin: 0; padding-left: 20px; color: #2b2a26; }
.lpd-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .lpd-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

