(function() {
    'use strict';

    class LaunchpadAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Launchpad LatAm`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (ONEI · Republic of Aurelia · AUP, pegged 1:1 to MXN).
            this.BUDGET = 1800;              // AUP 1,800M discretionary program envelope
            this.BASE_TEA = 14.0;           // baseline early-stage activity rate (%)
            this.BASE_HG = 8.0;             // baseline high-growth aspiration share (%)
            this.BASE_SURVIVAL = 42;        // baseline 3-year survival rate (%)
            this.NECESSITY_SHARE = 62;      // % of starts that are necessity-driven
            this.REFORM_COST = {            // AUP M fiscal cost per reform option
                registration: 80,
                tax: 120,
                insolvency: 180,
                equity: 260
            };
            // Which segment each reform primarily serves.
            this.REFORM_SEGMENT = {
                registration: `necessity`,
                tax: `necessity`,
                insolvency: `highgrowth`,
                equity: `highgrowth`
            };
            // Levers grouped by the segment they primarily tilt toward.
            this.HG_LEVERS = [`seed`, `accel`, `guarantee`, `rd`];
            this.NEC_LEVERS = [`training`, `formalise`];

            // Concept truths.
            this.TRUE_DIAGNOSIS = `bimodal`;
            this.TRUE_CONSTRAINT = `finance`;
            this.TRUE_POSTURE = `portfolio`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    formation: this.BASE_TEA,    // TEA, new-firm formation rate (%)
                    highgrowth: this.BASE_HG,    // high-growth aspiration share (%)
                    survival: this.BASE_SURVIVAL,// 3-year survival rate (%)
                    efficiency: 50,              // budget efficiency, outcome per peso (0–100)
                    viability: 50,               // political viability (0–100)
                    budgetUsed: 0,               // AUP M committed (levers + reform), set in R3
                    overBudget: false,           // breached AUP 1.8B / assumed new debt
                    undifferentiated: false,      // treated entrepreneurship as one thing
                    reformMismatch: false,        // reform served the wrong segment
                    formationHistory: [this.BASE_TEA],
                    highgrowthHistory: [this.BASE_HG],
                    viabilityHistory: [50],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must NOT auto-win: an even allocation across
                // all six levers is the "treat entrepreneurship as one thing" error,
                // and the cheap registration reform mismatches a high-growth tilt.
                state.decisions = {
                    diagnosis: `bimodal`,
                    constraint: `finance`,
                    depth: 50,
                    posture: `portfolio`,
                    tilt: 50,
                    kpi: `both`,
                    seed: 300, accel: 300, guarantee: 300,
                    training: 300, formalise: 300, rd: 300,
                    reform: `registration`,
                    defence: `dualkpi`,
                    fiscal: `costed`,
                    partner: `aligned`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagnosisInput`);
                const co = document.getElementById(`constraintInput`);
                const de = document.getElementById(`depthInput`);
                if (dg) decisions.diagnosis = dg.value;
                if (co) decisions.constraint = co.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 2) {
                const po = document.getElementById(`postureInput`);
                const ti = document.getElementById(`tiltInput`);
                const kp = document.getElementById(`kpiInput`);
                if (po) decisions.posture = po.value;
                if (ti) decisions.tilt = parseInt(ti.value, 10);
                if (kp) decisions.kpi = kp.value;
                if (!Number.isFinite(decisions.tilt) || decisions.tilt < 0 || decisions.tilt > 100) {
                    warn(`warn_tilt_range`); return false;
                }
            } else if (round === 3) {
                const ids = [`seed`, `accel`, `guarantee`, `training`, `formalise`, `rd`];
                ids.forEach((id) => {
                    const el = document.getElementById(id + `Input`);
                    if (el) decisions[id] = parseFloat(el.value);
                });
                const rf = document.getElementById(`reformInput`);
                if (rf) decisions.reform = rf.value;
                if (ids.some((id) => !Number.isFinite(decisions[id]) || decisions[id] < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                if (!this.REFORM_COST.hasOwnProperty(decisions.reform)) {
                    warn(`warn_reform_missing`); return false;
                }
                const leverTotal = ids.reduce((s, id) => s + decisions[id], 0);
                const reformCost = this.REFORM_COST[decisions.reform] || 0;
                // The six levers PLUS the chosen reform must fit inside the AUP 1.8B
                // envelope with no new debt. Overspending is blocked here; the costed
                // plan is the hard fiscal constraint (Common Error 5). A reform must be
                // funded by trimming levers — the seeded 1,800M of levers + any reform
                // breaches the cap, so a blind click-through cannot pass this round.
                if (leverTotal + reformCost > this.BUDGET + 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const df = document.getElementById(`defenceInput`);
                const fi = document.getElementById(`fiscalInput`);
                const pa = document.getElementById(`partnerInput`);
                const cv = document.getElementById(`convictionInput`);
                if (df) decisions.defence = df.value;
                if (fi) decisions.fiscal = fi.value;
                if (pa) decisions.partner = pa.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite (was computed only in getPerformanceSummary and discarded).
            const formation = ds.formation;
            const highgrowth = ds.highgrowth;
            const survival = ds.survival;
            const efficiency = Math.round(ds.efficiency);
            const viability = Math.round(ds.viability);
            const formationGain = formation - this.BASE_TEA;
            const highgrowthGain = highgrowth - this.BASE_HG;
            const formScore = Math.max(0, Math.min(100, (formationGain / 4) * 100));
            const hgScore = Math.max(0, Math.min(100, (highgrowthGain / 4) * 100));
            let comp = Math.round(
                formScore * 0.22 + hgScore * 0.22 + efficiency * 0.20 + viability * 0.24 + ((survival - 25) / 50 * 100) * 0.12
            );
            if (ds.reformMismatch) comp = Math.max(0, comp - 12);
            return comp;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let formDelta = 0, hgDelta = 0, survDelta = 0, effDelta = 0, viaDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the bimodal ecosystem (Common Error 1: one undifferentiated target).
                switch (d.diagnosis) {
                    case `bimodal`:
                        effDelta += 10; viaDelta += 4; coachKey = `coach_r1_bimodal`; break;
                    case `onething`:
                        ds.undifferentiated = true; effDelta -= 8; viaDelta -= 2; coachKey = `coach_r1_onething`; break;
                    case `lowtotal`:
                        effDelta -= 5; coachKey = `coach_r1_lowtotal`; break;
                    case `elite`:
                        effDelta -= 4; viaDelta -= 6; coachKey = `coach_r1_elite`; break;
                }

                // Name the constraint that actually binds for the high-growth segment.
                switch (d.constraint) {
                    case `finance`: effDelta += 8; hgDelta += 0.3; if (d.diagnosis === `bimodal`) coachKey = `coach_r1_sharp`; break;
                    case `registration`: effDelta -= 4; coachKey = `coach_r1_wrongcon`; break;
                    case `training`: effDelta -= 4; break;
                    case `demand`: effDelta -= 6; viaDelta -= 2; coachKey = `coach_r1_demand`; break;
                }

                // Depth of segment separation underpins every later decision.
                if (d.depth >= 60) { effDelta += 6; viaDelta += 3; }
                else if (d.depth <= 25) { effDelta -= 6; coachKey = `coach_r1_shallow`; }

                summaryKey = (d.diagnosis === `bimodal` && d.constraint === `finance`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the targeting posture (Common Errors 1, 2 & 3).
                const tilt = d.tilt / 100;            // 0 = all necessity, 1 = all high-growth
                // A balanced-but-deliberate tilt (≈55–70% high-growth) honours BOTH KPIs.
                // Distance from the ideal high-growth weight (0.62) drives a quadratic penalty.
                const ideal = 0.62;
                const miss = Math.abs(tilt - ideal);

                switch (d.posture) {
                    case `portfolio`:
                        viaDelta += 6; effDelta += 6; coachKey = `coach_r2_portfolio`;
                        // Portfolio rewards both KPIs, scaled by how well-tilted it is.
                        formDelta += 0.8 * (1 - tilt) + 0.4;
                        hgDelta += 0.9 * tilt + 0.2;
                        break;
                    case `highgrowth`:
                        // Over-concentration: dynamism up, but formation flat and backlash.
                        hgDelta += 1.6; formDelta += 0.1; viaDelta -= 12; effDelta -= 2;
                        coachKey = `coach_r2_highgrowth`;
                        break;
                    case `necessity`:
                        // Necessity-only: formation up, but high-growth flat, partner unhappy.
                        formDelta += 1.4; hgDelta += 0.0; survDelta += 2; viaDelta += 4; effDelta -= 4;
                        coachKey = `coach_r2_necessity`;
                        break;
                    case `even`:
                        // Treat entrepreneurship as one thing: misfires for both segments.
                        ds.undifferentiated = true;
                        formDelta += 0.3; hgDelta += 0.2; effDelta -= 8; viaDelta -= 2;
                        coachKey = `coach_r2_even`;
                        break;
                }

                // The tilt quality only matters for a deliberate portfolio.
                if (d.posture === `portfolio`) {
                    if (miss <= 0.12) { effDelta += 6; hgDelta += 0.5; formDelta += 0.3; }
                    else if (miss >= 0.30) { effDelta -= 5; coachKey = (tilt > ideal) ? `coach_r2_tilthigh` : `coach_r2_tiltlow`; }
                }

                // Tie the posture to a KPI logic.
                switch (d.kpi) {
                    case `both`: viaDelta += 5; effDelta += 4; break;
                    case `formation`: hgDelta -= 0.3; coachKey = (coachKey === `coach_r2_portfolio`) ? `coach_r2_kpiformation` : coachKey; break;
                    case `highgrowth`: formDelta -= 0.3; viaDelta -= 3; break;
                    case `none`: ds.undifferentiated = true; effDelta -= 6; viaDelta -= 4; coachKey = `coach_r2_kpinone`; break;
                }

                summaryKey = (d.posture === `portfolio` && d.kpi === `both`) ? `sum_r2_good` :
                             (d.posture === `highgrowth` ? `sum_r2_concentrated` :
                             (d.posture === `necessity` ? `sum_r2_necessity` : `sum_r2_weak`));
            } else if (round === 3) {
                // Allocate AUP 1.8B + choose the reform (Common Errors 4 & 5).
                const hgSpend = this.HG_LEVERS.reduce((s, id) => s + (d[id] || 0), 0);
                const necSpend = this.NEC_LEVERS.reduce((s, id) => s + (d[id] || 0), 0);
                const leverTotal = hgSpend + necSpend;
                const reformCost = this.REFORM_COST[d.reform] || 0;
                const allocHgShare = leverTotal > 0 ? hgSpend / leverTotal : 0.5;

                // Allocation lifts the KPI of the segment it funds.
                formDelta += (necSpend / this.BUDGET) * 2.2;       // necessity levers → formation
                hgDelta += (hgSpend / this.BUDGET) * 2.4;          // high-growth levers → dynamism
                survDelta += (necSpend / this.BUDGET) * 4 + (hgSpend / this.BUDGET) * 2;

                // Deploy the envelope: leaving the budget largely unspent is a missed
                // opportunity (validation already blocks overspend / new debt).
                const deployed = leverTotal + reformCost;
                if (deployed < this.BUDGET * 0.85) { effDelta -= 4; }
                else { effDelta += 3; }

                // Allocation must be consistent with the Round-2 posture/tilt.
                const targetShare = (d.posture === `highgrowth`) ? 0.85 :
                                    (d.posture === `necessity`) ? 0.25 :
                                    (d.posture === `even`) ? 0.5 :
                                    (d.tilt / 100);               // portfolio honours the stated tilt
                const incoherence = Math.abs(allocHgShare - targetShare);
                if (incoherence <= 0.12) { effDelta += 8; viaDelta += 3; coachKey = `coach_r3_coherent`; }
                else { effDelta -= 8; coachKey = `coach_r3_incoherent`; }

                // Concentration penalty: dumping almost everything into the HG levers
                // is the "subsidies for elites" backlash even if it lifts dynamism.
                if (allocHgShare >= 0.85) { viaDelta -= 10; hgDelta += 0.4; formDelta -= 0.4; if (coachKey === `coach_r3_coherent`) coachKey = `coach_r3_elitebacklash`; }
                else if (allocHgShare <= 0.18) { hgDelta -= 0.5; effDelta -= 3; if (coachKey === `coach_r3_coherent`) coachKey = `coach_r3_survivalonly`; }

                // Reform–segment alignment (Common Error 4). "Target segment" is the
                // side the budget actually tilted toward.
                const budgetSegment = allocHgShare >= 0.55 ? `highgrowth` : (allocHgShare <= 0.45 ? `necessity` : `balanced`);
                const reformSeg = this.REFORM_SEGMENT[d.reform];
                if (budgetSegment === `balanced` || reformSeg === budgetSegment) {
                    effDelta += 6; viaDelta += 2;
                    if (reformSeg === `highgrowth`) hgDelta += 0.6; else formDelta += 0.5;
                    if (d.reform === `registration` || d.reform === `tax`) survDelta += 2; // formalisation lifts survival
                    if (d.reform === `equity`) hgDelta += 0.4;                            // finance/exit really moves dynamism
                } else {
                    ds.reformMismatch = true;
                    // A first-order lever spent on the wrong segment: the reform fails to
                    // relieve the constraint the budget targets, so the targeted KPI stalls.
                    effDelta -= 14; viaDelta -= 6;
                    if (budgetSegment === `highgrowth`) hgDelta -= 0.8; else formDelta -= 0.7;
                    coachKey = `coach_r3_reformmismatch`;
                }

                // Hard fiscal constraint (Common Error 5): levers + reform must fit AUP 1.8B.
                ds.budgetUsed = Math.round(leverTotal + reformCost);
                if (ds.budgetUsed > this.BUDGET) {
                    ds.overBudget = true;
                    effDelta -= 14; viaDelta -= 14; formDelta -= 0.6; hgDelta -= 0.4;
                    coachKey = `coach_r3_overbudget`;
                } else {
                    viaDelta += 4;
                }

                summaryKey = ds.overBudget ? `sum_r3_overbudget` :
                             (ds.reformMismatch ? `sum_r3_mismatch` :
                             (incoherence <= 0.12 ? `sum_r3_good` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the plan to the cabinet (Pedagogical Objective 5).
                switch (d.defence) {
                    case `dualkpi`: viaDelta += 12; effDelta += 4; coachKey = `coach_r4_dualkpi`; break;
                    case `jobs`: formDelta += 0.3; viaDelta += 2; hgDelta -= 0.2; coachKey = `coach_r4_jobs`; break;
                    case `productivity`: hgDelta += 0.3; viaDelta -= 6; coachKey = `coach_r4_productivity`; break;
                    case `vision`: viaDelta -= 8; effDelta -= 4; coachKey = `coach_r4_vision`; break;
                }

                // The Finance Minister on the no-new-debt limit.
                switch (d.fiscal) {
                    case `costed`: viaDelta += 10; effDelta += 6; if (!ds.overBudget) coachKey = `coach_r4_costed`; break;
                    case `trim`: viaDelta -= 4; effDelta -= 3; break;
                    case `borrow`: viaDelta -= 12; effDelta -= 4; ds.overBudget = true; coachKey = `coach_r4_borrow`; break;
                    case `vague`: viaDelta -= 8; effDelta -= 5; coachKey = `coach_r4_vague`; break;
                }

                // The development partner on where the scalable firms come from.
                switch (d.partner) {
                    case `aligned`: hgDelta += 0.5; viaDelta += 6; effDelta += 3; if (d.defence === `dualkpi` && d.fiscal === `costed`) coachKey = `coach_r4_landed`; break;
                    case `hope`: viaDelta -= 3; coachKey = `coach_r4_hope`; break;
                    case `later`: hgDelta -= 0.2; viaDelta -= 2; break;
                    case `deflect`: viaDelta -= 6; effDelta -= 3; coachKey = `coach_r4_deflect`; break;
                }

                if (d.conviction >= 60) { viaDelta += 5; }
                else if (d.conviction <= 25) { viaDelta -= 5; }

                summaryKey = (d.defence === `dualkpi` && d.fiscal === `costed` && d.partner === `aligned`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with realistic clamps.
            ds.formation = Math.round(Math.max(8, Math.min(26, ds.formation + formDelta)) * 10) / 10;
            ds.highgrowth = Math.round(Math.max(4, Math.min(22, ds.highgrowth + hgDelta)) * 10) / 10;
            ds.survival = Math.max(25, Math.min(75, Math.round(ds.survival + survDelta)));
            ds.efficiency = Math.max(0, Math.min(100, Math.round(ds.efficiency + effDelta)));
            ds.viability = Math.max(0, Math.min(100, Math.round(ds.viability + viaDelta)));

            ds.formationHistory.push(ds.formation);
            ds.highgrowthHistory.push(ds.highgrowth);
            ds.viabilityHistory.push(ds.viability);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 - persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                formation: ds.formation,
                formationDelta: Math.round(formDelta * 10) / 10,
                highgrowth: ds.highgrowth,
                highgrowthDelta: Math.round(hgDelta * 10) / 10,
                survival: ds.survival,
                efficiency: ds.efficiency,
                efficiencyDelta: Math.round(effDelta),
                viability: ds.viability,
                viabilityDelta: Math.round(viaDelta),
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                reformMismatch: ds.reformMismatch,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // AUP, pegged 1:1 to MXN for modelling. Locale-aware thousands separator:
            // English "AUP 1,800M", Spanish "AUP 1.800M". One consistent notation, never a bare "$".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) || 0);
            const grouped = n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, lang === `es` ? `.` : `,`);
            return `AUP ` + grouped + `M`;
        }

        _fmtPct1(v) {
            // One-decimal percentage, locale-aware decimal mark.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = (Number(v) || 0).toFixed(1);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return s + `%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`formationDisplay`, `domainState.formation`, (v) => self._fmtPct1(Number(v)));
            uiManager.bind(`highgrowthDisplay`, `domainState.highgrowth`, (v) => self._fmtPct1(Number(v)));
            uiManager.bind(`survivalDisplay`, `domainState.survival`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`efficiencyDisplay`, `domainState.efficiency`, (v) => Math.round(Number(v)));
            uiManager.bind(`viabilityDisplay`, `domainState.viability`, (v) => {
                const card = document.querySelector(`.launchpadsim-card-viability`);
                if (card) {
                    card.classList.toggle(`launchpadsim-viability-high`, Number(v) >= 65);
                    card.classList.toggle(`launchpadsim-viability-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.launchpadsim-budget-bar`);
                if (bar) bar.classList.toggle(`launchpadsim-budget-over`, Number(v) > self.BUDGET);
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
            });

            // Depth slider readout.
            const de = document.getElementById(`depthInput`);
            const deReadout = document.getElementById(`depthReadout`);
            if (de && deReadout) {
                deReadout.textContent = de.value;
                de.addEventListener(`input`, function() { deReadout.textContent = de.value; });
            }

            // Tilt slider readout.
            const ti = document.getElementById(`tiltInput`);
            const tiReadout = document.getElementById(`tiltReadout`);
            if (ti && tiReadout) {
                tiReadout.textContent = ti.value;
                ti.addEventListener(`input`, function() { tiReadout.textContent = ti.value; });
            }

            // Live committed total = six levers + the chosen reform; must fit AUP 1,800M.
            const allocIds = [`seedInput`, `accelInput`, `guaranteeInput`, `trainingInput`, `formaliseInput`, `rdInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const reformEl = document.getElementById(`reformInput`);
            const recompute = function() {
                let levers = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) levers += (parseFloat(el.value) || 0);
                });
                const reformCost = (reformEl && self.REFORM_COST[reformEl.value]) || 0;
                const committed = Math.round(levers + reformCost);
                if (allocReadout) allocReadout.textContent = committed;
                const bar = document.querySelector(`.launchpadsim-alloc-readout`);
                // Red only on a true overspend (no new debt); underspend is allowed.
                if (bar) bar.style.color = (committed > self.BUDGET + 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            if (reformEl) reformEl.addEventListener(`change`, recompute);
            recompute();
        }

