        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.formationHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                launchpadChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.formationHistory },
                        { data: ds.highgrowthHistory },
                        { data: ds.viabilityHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const formation = ds.formation;
            const highgrowth = ds.highgrowth;
            const survival = ds.survival;
            const efficiency = Math.round(ds.efficiency);
            const viability = Math.round(ds.viability);

            // Did the plan move BOTH headline KPIs the Directive demanded?
            const formationGain = formation - this.BASE_TEA;
            const highgrowthGain = highgrowth - this.BASE_HG;

            // Normalise gains: ~+4pts TEA and ~+4pts high-growth share are "full marks".
            const formScore = Math.max(0, Math.min(100, (formationGain / 4) * 100));
            const hgScore = Math.max(0, Math.min(100, (highgrowthGain / 4) * 100));

            // v1.1.0 - reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const balanced = formationGain >= 1.5 && highgrowthGain >= 1.5;
            const solvent = !ds.overBudget;
            const credible = viability >= 60 && efficiency >= 55;
            const aligned = !ds.reformMismatch;

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_missed`;
            if (!solvent) tierKey = `grade_budget`;
            else if (balanced && credible && aligned && composite >= 75) tierKey = `grade_signed`;
            else if (ds.reformMismatch && composite >= 55) tierKey = `grade_reform`;
            else if (ds.undifferentiated || (formationGain < 1 && highgrowthGain < 1)) tierKey = `grade_undiff`;
            else if (highgrowthGain >= 2 && formationGain < 0.8) tierKey = `grade_elite`;
            else if (formationGain >= 2 && highgrowthGain < 0.8) tierKey = `grade_survival`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (!solvent) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (balanced && credible) insights.push(window.mySimulation.t(`insight_balanced`));
            else if (ds.undifferentiated) insights.push(window.mySimulation.t(`insight_undifferentiated`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (highgrowthGain >= 2 && formationGain < 0.8) insights.push(window.mySimulation.t(`insight_elite`));
            if (formationGain >= 2 && highgrowthGain < 0.8) insights.push(window.mySimulation.t(`insight_necessity`));
            if (ds.reformMismatch) insights.push(window.mySimulation.t(`insight_reformmismatch`));
            if (viability < 40) insights.push(window.mySimulation.t(`insight_viability`));
            if (balanced && solvent && viability >= 65) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                formation: formation,
                highgrowth: highgrowth,
                survival: survival,
                efficiency: efficiency,
                viability: viability,
                balanced: balanced,
                solvent: solvent,
                credible: credible,
                aligned: aligned,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="lpd-cm"><p class="lpd-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="lpd-cm-chip ` + (ok ? `lpd-cm-ok` : `lpd-cm-no`) + `">` +
                `<span class="lpd-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="lpd-cm-kpi"><div class="lpd-cm-kpi-val">` + val +
                `</div><div class="lpd-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="lpd-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="lpd-cm">` +
  `<div class="lpd-cm-head">` +
    `<div class="lpd-cm-score"><div class="lpd-cm-score-num">` + Math.round(s.composite) +
       `<span class="lpd-cm-score-den">/100</span></div>` +
       `<div class="lpd-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="lpd-cm-verdict"><div class="lpd-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="lpd-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="lpd-cm-section"><div class="lpd-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="lpd-cm-chips">` + chip(!!s.balanced, t(`cm_t_balanced`)) + chip(!!s.solvent, t(`cm_t_solvent`)) +
      chip(!!s.credible, t(`cm_t_credible`)) + chip(!!s.aligned, t(`cm_t_aligned`)) + `</div></div>` +
  `<div class="lpd-cm-section"><div class="lpd-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="lpd-cm-kpis">` +
      kpi(t(`cm_lbl_formation`), Number(s.formation).toFixed(1) + `%`, t(`cm_sub_formation`)) +
      kpi(t(`cm_lbl_highgrowth`), Number(s.highgrowth).toFixed(1) + `%`, t(`cm_sub_highgrowth`)) +
      kpi(t(`cm_lbl_efficiency`), Math.round(s.efficiency), t(`cm_sub_efficiency`)) +
      kpi(t(`cm_lbl_viability`), Math.round(s.viability), t(`cm_sub_viability`)) +
    `</div></div>` +
  (insights ? `<div class="lpd-cm-section"><div class="lpd-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="lpd-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.undifferentiated) return window.mySimulation.t(`hint_undifferentiated`);
            if (ds.reformMismatch) return window.mySimulation.t(`hint_reformmismatch`);
            if (ds.viability <= 30) return window.mySimulation.t(`hint_viability`);
            if (state.currentPeriod >= 3 && (ds.highgrowth - this.BASE_HG) < 0.8) return window.mySimulation.t(`hint_highgrowth`);
            if (state.currentPeriod >= 3 && (ds.formation - this.BASE_TEA) < 0.8) return window.mySimulation.t(`hint_formation`);
            if (ds.viability >= 65 && ds.efficiency >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.formation`, label: `Formation`, i18nKey: `col_formation`, formatter: (v) => self._fmtPct1(Number(v)) },
                { key: `results.highgrowth`, label: `High-Growth`, i18nKey: `col_highgrowth`, formatter: (v) => self._fmtPct1(Number(v)) },
                { key: `results.efficiency`, label: `Efficiency`, i18nKey: `col_efficiency`, formatter: (v) => Math.round(v) },
                { key: `results.viability`, label: `Viability`, i18nKey: `col_viability`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

